import pytest

from code_health.report import review_source

DEEP = "class C { void M(int a) { if (a > 0) { if (a > 1) { if (a > 2) { if (a > 3) { } } } } } }\n"


@pytest.mark.parametrize(
    "header",
    [
        "// <auto-generated>\n//     Generated by a tool.\n// </auto-generated>\n",
        "﻿// <auto-generated />\n",
        "// @generated by protoc\n",
        "// Code generated by mockgen. DO NOT EDIT.\n",
    ],
    ids=["dotnet block", "dotnet with BOM", "@generated", "do not edit"],
)
def test_generated_files_are_not_scored(header):
    report = review_source("Model.cs", (header + DEEP).encode())

    assert (report.score, report.reason) == (None, "generated")


def test_marker_must_be_in_the_header():
    source = DEEP + "// <auto-generated> appears later, in a comment about something else\n"

    assert review_source("Model.cs", source.encode()).score is not None


def test_hand_written_file_mentioning_generation_is_scored():
    source = "// Generates invoices; nothing here is generated.\n" + DEEP

    assert review_source("Model.cs", source.encode()).score is not None
